fn register_predicate_obligation(
        &mut self,
        infcx: &InferCtxt<'tcx>,
        obligation: PredicateObligation<'tcx>,
    ) {
        // this helps to reduce duplicate errors, as well as making
        // debug output much nicer to read and so on.
        let obligation = infcx.resolve_vars_if_possible(obligation);

        debug!(?obligation, "register_predicate_obligation");

        assert!(!infcx.is_in_snapshot() || self.usable_in_snapshot);

        super::relationships::update(self, infcx, &obligation);

        self.predicates
            .register_obligation(PendingPredicateObligation { obligation, stalled_on: vec![] });
    }

pub struct FulfillmentContext<'tcx> {
    // A list of all obligations that have been registered with this
    // fulfillment context.
    predicates: ObligationForest<PendingPredicateObligation<'tcx>>,

    relationships: FxHashMap<ty::TyVid, ty::FoundRelationships>,

    // Is it OK to register obligations into this infcx inside
    // an infcx snapshot?
    //
    // The "primary fulfillment" in many cases in typeck lives
    // outside of any snapshot, so any use of it inside a snapshot
    // will lead to trouble and therefore is checked against, but
    // other fulfillment contexts sometimes do live inside of
    // a snapshot (they don't *straddle* a snapshot, so there
    // is no trouble there).
    usable_in_snapshot: bool,
}

fn infer_opaque_definition_from_instantiation(
        &self,
        opaque_type_key: OpaqueTypeKey<'tcx>,
        instantiated_ty: OpaqueHiddenType<'tcx>,
        origin: OpaqueTyOrigin,
    ) -> Ty<'tcx> {
        if self.is_tainted_by_errors() {
            return self.tcx.ty_error();
        }

        let definition_ty = instantiated_ty
            .remap_generic_params_to_declaration_params(opaque_type_key, self.tcx, false, origin)
            .ty;

        if !check_opaque_type_parameter_valid(
            self.tcx,
            opaque_type_key,
            origin,
            instantiated_ty.span,
        ) {
            return self.tcx.ty_error();
        }

        // Only check this for TAIT. RPIT already supports `src/test/ui/impl-trait/nested-return-type2.rs`
        // on stable and we'd break that.
        let OpaqueTyOrigin::TyAlias = origin else {
            return definition_ty;
        };
        let def_id = opaque_type_key.def_id;
        // This logic duplicates most of `check_opaque_meets_bounds`.
        // FIXME(oli-obk): Also do region checks here and then consider removing `check_opaque_meets_bounds` entirely.
        let param_env = self.tcx.param_env(def_id);
        let body_id = self.tcx.local_def_id_to_hir_id(def_id);
        // HACK This bubble is required for this tests to pass:
        // type-alias-impl-trait/issue-67844-nested-opaque.rs
        let infcx =
            self.tcx.infer_ctxt().with_opaque_type_inference(DefiningAnchor::Bubble).build();
        // Require the hidden type to be well-formed with only the generics of the opaque type.
        // Defining use functions may have more bounds than the opaque type, which is ok, as long as the
        // hidden type is well formed even without those bounds.
        let predicate = ty::Binder::dummy(ty::PredicateKind::WellFormed(definition_ty.into()))
            .to_predicate(infcx.tcx);
        let mut fulfillment_cx = <dyn TraitEngine<'tcx>>::new(infcx.tcx);

        let id_substs = InternalSubsts::identity_for_item(self.tcx, def_id.to_def_id());

        // Require that the hidden type actually fulfills all the bounds of the opaque type, even without
        // the bounds that the function supplies.
        match infcx.register_hidden_type(
            OpaqueTypeKey { def_id, substs: id_substs },
            ObligationCause::misc(instantiated_ty.span, body_id),
            param_env,
            definition_ty,
            origin,
        ) {
            Ok(infer_ok) => {
                for obligation in infer_ok.obligations {
                    fulfillment_cx.register_predicate_obligation(&infcx, obligation);
                }
            }
            Err(err) => {
                infcx
                    .err_ctxt()
                    .report_mismatched_types(
                        &ObligationCause::misc(instantiated_ty.span, body_id),
                        self.tcx.mk_opaque(def_id.to_def_id(), id_substs),
                        definition_ty,
                        err,
                    )
                    .emit();
            }
        }

        fulfillment_cx.register_predicate_obligation(
            &infcx,
            Obligation::misc(instantiated_ty.span, body_id, param_env, predicate),
        );

        // Check that all obligations are satisfied by the implementation's
        // version.
        let errors = fulfillment_cx.select_all_or_error(&infcx);

        // This is still required for many(half of the tests in ui/type-alias-impl-trait)
        // tests to pass
        let _ = infcx.inner.borrow_mut().opaque_type_storage.take_opaque_types();

        if errors.is_empty() {
            definition_ty
        } else {
            infcx.err_ctxt().report_fulfillment_errors(&errors, None, false);
            self.tcx.ty_error()
        }
    }
